-- Source-backed Delexes University College programme catalogue.
-- Official listing currently names ten main undergraduate programmes; do not pad to thirty with invented degrees.
-- Programmes and semester course lists reviewed from direct official programme pages on 2026-10-13.
BEGIN;

UPDATE public.universities
SET
  website_url = 'https://delexesuniversity.edu.gh/',
  admissions_url = 'https://delexesuniversity.edu.gh/admissions/',
  logo_url = COALESCE(logo_url, 'https://admission.delexesuniversity.edu.gh/assets/logo.png'),
  logo_source_url = COALESCE(logo_source_url, 'https://admission.delexesuniversity.edu.gh/assets/logo.png'),
  campus_image_url = COALESCE(campus_image_url, 'https://delexesuniversity.edu.gh/wp-content/uploads/2025/01/campus.jpg'),
  campus_image_source_url = COALESCE(campus_image_source_url, 'https://delexesuniversity.edu.gh/wp-content/uploads/2025/01/campus.jpg'),
  campus_image_resolved_at = COALESCE(campus_image_resolved_at, now()),
  logo_verification_status = CASE WHEN COALESCE(logo_url, logo_source_url) IS NULL THEN 'verified' ELSE logo_verification_status END,
  logo_verified_at = COALESCE(logo_verified_at, now()),
  last_verified_at = now(),
  source_urls = ARRAY(
    SELECT DISTINCT src
    FROM unnest(COALESCE(source_urls, ARRAY[]::text[]) || ARRAY[
      'https://delexesuniversity.edu.gh/',
      'https://delexesuniversity.edu.gh/undergraduate/',
      'https://delexesuniversity.edu.gh/admissions/'
    ]) AS src
  ),
  updated_at = now()
WHERE slug = 'delexes-university-college';

