Physiology I","DUMD 115: Applied Chemistry","DUMD 117: Basic Nursing I","DUMD 119: Professional Adjustment in Midwifery"]},{"year_label":"Level 100 · Semester 2","position":2,"courses":["DUMD 100: Introduction to New Testament (CRPrincs)","DUMD 102: Sociology for Nurses/Midwives","DUMD 104: Information and Communication Technology","DUMD 106: Human Anatomy II","DUMD 108: Physiology II","DUMD 110: Applied Physics","DUMD 112: Basic Nursing II","DUMD 114: First Aid and Disaster Management","DUMD 116: Therapeutic Communication","DUMV 132: Intra-Semester Clinical Practice","DUMV 134: Long Vacation Practice I (Basic Nursing Procedures)"]},{"year_label":"Level 200 · Semester 1","position":3,"courses":["DUMD 201: Fundamentals of Entrepreneurship","DUMD 203: Microbiology, Parasitology and Infection Prevention & Control","DUMD 205: Health Assessment","DUMD 207: Pharmacology for Nurses I","DUMD 209: Introduction to Community Health Nursing","DUMV 231: Intra-Semester Clinical Practice II","DUMD 211: Antepartum Care I","DUMD 213: Anatomy and Physiology of Human Reproductive System and Foetus I","DUMD 215: Medical Nursing for Midwives I","DUMD 217: Surgical Nursing for Midwives I"]},{"year_label":"Level 200 · Semester 2","position":4,"courses":["DUMD 200: Pathology","DUMD 202: Nutrition and Dietetics","DUMD 204: Prevention and Control of Communicable Diseases","DUMD 206: Pharmacology for Nurses II","DUMD 208: Antepartum Care II","DUMD 210: Anatomy and Physiology of Human Reproductive System and Foetus II","DUMD 212: Medical Nursing for Midwives II","DUMD 214: Surgical Nursing for Midwives II","DUMV 232: Intra-Semester Clinical Practice III","DUMD 216: Advanced Nursing","DUMD 218: Mental Health Nursing I","DUMV 234: Long Vacation Practice II (Medical surgical / Mental health / Antepartum Care)"]},{"year_label":"Level 300 · Semester 1","position":5,"courses":["DUMD 301: Introduction to French for Healthcare","DUMD 303: Introduction to Sign Language","DUMD 305: Nursing Informatics","DUMD 307: Biostatistics","DUMD 309: Gerontology and Home Nursing","DUMV 331: Intra-Semester Midwifery Practicum I","DUMD 311: Intrapartum Care I","DUMD 313: Neonatal Nursing","DUMD 315: Gynaecology and Reproductive Tract Infections","DUMD 317: Nursing Research Methods"]},{"year_label":"Level 300 · Semester 2","position":6,"courses":["DUMD 300: Domiciliary Midwifery","DUMD 302: Intrapartum Care II","DUMD 304: Obstetrics Pharmacotherapeutics","DUMD 306: Mental Health Nursing II","DUMV 332: Intra-Semester Midwifery Practicum II","DUMD 308: Reproductive Health (Family Planning)","DUMD 310: Nursing and Midwifery Theories","DUMD 312: Introduction to Palliative Care","DUMV 334: Long Vacation Practice III (Reproductive health, Domiciliary midwifery practice)"]},{"year_label":"Level 400 · Semester 1","position":7,"courses":["DUMD 401: Teaching and Learning in Healthcare","DUMD 403: Ethics","DUMV 431: Intra-Semester Midwifery Practicum III","DUMD 405: Paediatric Nursing","DUMD 407: Post Partum Care","DUMD 409: Adolescent Health and Development","DUMD 411: Public Health Nursing","DUMD 413: Family Centred Maternity Care Study","DUMD 415: Maternal and Neonatal Audit","DUMD 417: Child Health Protection and Abuse"]},{"year_label":"Level 400 · Semester 2","position":8,"courses":["DUMD 400: Research Project","DUMD 402: Nursing Administration and Management","DUMD 404: Supply Chain Management","DUMD 406: Occupational Health Nursing","DUMD 408: Nursing Seminar","DUMV 432: Intra-Semester Midwifery Practicum IV","DUMD 410: Obstetrics-Gynaecological Surgery, and Anaesthesia"]}]}]$catalogue$::jsonb AS body
),
items AS (
  SELECT value AS item
  FROM payload
  CROSS JOIN LATERAL jsonb_array_elements(payload.body)
),
institution AS (
  SELECT id
  FROM public.universities
  WHERE slug = 'delexes-university-college'
),
upserted AS (
  INSERT INTO public.programmes (
    university_id, slug, name, description, degree_type, duration, field,
    programme_url, application_url, qualification, mode, source_url, source_urls,
    verified, last_verified_at, verification_status, department, needs_review,
    verification_notes, verification_method, updated_at
  )
  SELECT
    institution.id,
    item->>'slug',
    item->>'name',
    item->>'description',
    item->>'degree_type',
    item->>'duration',
    item->>'field',
    item->>'programme_url',
    item->>'application_url',
    item->>'qualification',
    item->>'mode',
    item->>'programme_url',
    ARRAY[item->>'programme_url', 'https://delexesuniversity.edu.gh/undergraduate/']::text[],
    true,
    now(),
    'verified',
    item->>'department',
    false,
    'Programme name and published semester curriculum matched to the institution official programme page on 2026-10-13. This source check does not independently confirm accreditation or professional registration.',
    'Official institutional programme page',
    now()
  FROM items
  CROSS JOIN institution
  ON CONFLICT ON CONSTRAINT programmes_unique_per_university
  DO UPDATE SET
    slug = EXCLUDED.slug,
    description = EXCLUDED.description,
    degree_type = EXCLUDED.degree_type,
    duration = EXCLUDED.duration,
    field = EXCLUDED.field,
    programme_url = EXCLUDED.programme_url,
    application_url = EXCLUDED.application_url,
    qualification = EXCLUDED.qualification,
    mode = EXCLUDED.mode,
    source_url = EXCLUDED.source_url,
    source_urls = EXCLUDED.source_urls,
    verified = EXCLUDED.verified,
    last_verified_at = EXCLUDED.last_verified_at,
    verification_status = EXCLUDED.verification_status,
    department = EXCLUDED.department,
    needs_review = EXCLUDED.needs_review,
    verification_notes = EXCLUDED.verification_notes,
    verification_method = EXCLUDED.verification_method,
    updated_at = now()
  RETURNING id, slug, programme_url, university_id
),
curriculum_rows AS (
  SELECT
    u.id AS programme_id,
    c.value->>'year_label' AS year_label,
    (c.value->>'position')::integer AS position,
    ARRAY(SELECT jsonb_array_elements_text(c.value->'courses'))::text[] AS courses,
    'Official semester course list transcribed from the institution programme page: ' || u.programme_url AS note
  FROM items i
  JOIN upserted u ON u.slug = i.item->>'slug'
  CROSS JOIN LATERAL jsonb_array_elements(i.item->'curriculum') c(value)
),
curriculum_written AS (
  INSERT INTO public.programme_curriculum (
    programme_id, year_label, position, courses, note, source, updated_at
  )
  SELECT programme_id, year_label, position, courses, note, 'official', now()
  FROM curriculum_rows
  ON CONFLICT (programme_id, year_label)
  DO UPDATE SET
    position = EXCLUDED.position,
    courses = EXCLUDED.courses,
    note = EXCLUDED.note,
    source = 'official',
    updated_at = now()
  RETURNING id
),
sources_written AS (
  INSERT INTO public.programme_sources (
    programme_id, source_url, source_type, verification_status, verified_at
  )
  SELECT DISTINCT id, programme_url, 'programme_page', 'verified', now()
  FROM upserted
  ON CONFLICT (programme_id, source_url)
  DO UPDATE SET
    source_type = 'programme_page',
    verification_status = 'verified',
    verified_at = now()
  RETURNING id
)
SELECT
  (SELECT count(*) FROM upserted)::int AS programmes_upserted,
  (SELECT count(*) FROM curriculum_written)::int AS curriculum_semesters_upserted,
  (SELECT count(*) FROM sources_written)::int AS direct_official_source_links;

COMMIT;
